        $paths = self::PATHS[$name] ?? self::PATHS['box'];

        return new HtmlString(
            '<svg class="'.e($class).' shrink-0" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="'.e($strokeWidth)
